mapper.select:
SELECT id, user_id as userId, category, title, view_count as viewCount, comment_count as commentCount, DATE_FORMAT(created_at, '%Y-%m-%d %H:%i:%s') as createdAt FROM community_posts WHERE deleted_at IS NULL
AND (title LIKE CONCAT('%', #{search}, '%') OR content LIKE CONCAT('%', #{search}, '%'))
AND category = #{category} ORDER BY created_at DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM community_posts WHERE deleted_at IS NULL
AND (title LIKE CONCAT('%', #{search}, '%') OR content LIKE CONCAT('%', #{search}, '%'))
AND category = #{category}
